Definition allocate_post0 (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32)
    (n AB b1 : Z) (ctx : word) (uj : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + 128)) gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (AB + rz_size n)) a1' a2' a3' a4' a5'
                  a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(AB, AB + 16); (AB + rz_size n + -16, AB + rz_size n + Z.min n 4096); (bv_unsigned sp - 32, bv_unsigned sp + 128)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (AB + rz_size n + -16) [C1 (Z_to_bv 8 2); C1 (Z_to_bv 8 (Z.land b1 243)); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx]
    /\ rw_cells asegs m' (AB + rz_size n) [CB (Z.to_nat (Z.min n 4096)) uj]
    /\ (16 < rz_size n -> rw_cells asegs m' AB [C8 (Z_to_bv 64 K_kAllocBegMagic); C8 (Z_to_bv 64 (AB + rz_size n + -16))])%Z
    /\ stk asegs m' lo (bv_unsigned sp + 128).

Lemma allocate_p3b_tail0 : forall sp gp ra0 t0 t1 t2 a0v a1 a2v a3 a4 a5 a6 a7 t3 t4 t5 t6 s0v s6v s9v s3v
    fr0 fr1 fr2 fr3 fr4 fr5 fr6 fr7 fr8 fr9 fr10 fr11 fr12
    (F : bvmap 5 word) fc (m : mem) (n AB B T lo b1 : Z) (h0 uj lj j0 : list byte) (ctx : word),
  (1 <= n <= 2^31)%Z -> (kHighShadowEnd < AB)%Z -> (AB + needed2 n <= kHighMemEnd + 1)%Z -> (0 <= b1 < 256)%Z ->
  alloc_frame0 m (bv_unsigned sp) fr0 fr1 fr2 fr3 fr4 fr5 fr6 fr7 fr8 fr9 fr10 fr11 fr12 -> rw_cells asegs m (bv_unsigned sp) [CB 8 j0] ->
  rw_cells asegs m (AB + rz_size n + -16) [CB 1 h0; C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
  rw_cells asegs m (AB + rz_size n) [CB (Z.to_nat (Z.min n 4096)) uj] ->
  (16 < rz_size n -> rw_cells asegs m AB [CB 16 lj])%Z ->
  rw_cells asegs m g_GOT_asan_flags [C8 (Z_to_bv 64 g_asan_flags)] ->
  rw_cells asegs m (g_asan_flags + 44) [C4 (Z_to_bv 64 4096)] -> rw_cells asegs m (g_asan_flags + 52) [C4 (Z_to_bv 64 190)] ->
  setshadow_cells m ->
  rw_cells asegs m 0x226998 [C8 (Z_to_bv 64 32)] -> rw_cells asegs m (tpA + 32) [C4 (Z_to_bv 64 0)] ->
  rw_cells asegs m g_MFHooks [C8 (Z_to_bv 64 0)] ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 32)%Z -> (0x79a000 <= lo)%Z -> (bv_unsigned sp + 128 <= 2^63)%Z ->
  (AB + needed2 n <= lo)%Z ->
